// Transport selection order: --transport flag, then PP_MCP_TRANSPORT env,
// then the first transport declared in the spec (see MCPConfig.Transport).
// The flag surface lets one binary serve stdio locally and streamable HTTP
// when hosted in a container or remote sandbox, matching the Anthropic
// guidance that production agents need a remote option.

const (
	defaultHTTPAddr = "127.0.0.1:7777"
)

// version is the printed MCP server's version, overridable at build time via ldflags.
var version = "2026.8.1"

func main() {
	if err := cli.BindMCPServerProfile(); err != nil {
		fmt.Fprintf(os.Stderr, "MCP client-profile bind failed: %v\n", err)
		os.Exit(1)
	}
	s := server.NewMCPServer(
		"Jules",
		version,
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	transport := flag.String("transport", defaultTransport(), "MCP transport: stdio | http")
	addr := flag.String("addr", defaultHTTPAddr, "bind address for http transport (host:port or :port)")
	tlsCert := flag.String("tls-cert", "", "TLS certificate file (required for --transport http on a non-loopback --addr)")
	tlsKey := flag.String("tls-key", "", "TLS private key file (required for --transport http on a non-loopback --addr)")
	flag.Parse()

	switch strings.ToLower(*transport) {
	case "stdio":
		if err := server.ServeStdio(s); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	case "http":
		// The HTTP transport dispatches tools using this process's own
		// JULES_API_KEY -- it does not re-authenticate the caller per
		// request. Any reachable listener (not just non-loopback binds;
		// other local users can also reach 127.0.0.1) would let an
		// unauthenticated caller invoke destructive tools like
		// sessions_delete against the operator's account. Require a
		// bearer token unconditionally rather than trying to special-case
		// "safe" bind addresses.
		token := os.Getenv("JULES_MCP_HTTP_TOKEN")
		if token == "" {
			fmt.Fprintln(os.Stderr, "JULES_MCP_HTTP_TOKEN is required for --transport http (generate one with e.g. `openssl rand -hex 32`); refusing to start an unauthenticated remote listener")
			os.Exit(1)
		}
		useTLS := *tlsCert != "" && *tlsKey != ""
		// A bearer token sent over plaintext HTTP can be intercepted and
		// replayed by anything on the network path. Loopback-only binds
		// keep that path inside the local machine, so plaintext is
		// tolerated there; any address that could accept a connection from
		// another host requires TLS.
		if !useTLS && !isLoopbackAddr(*addr) {
			fmt.Fprintln(os.Stderr, "--tls-cert and --tls-key are required for --transport http on a non-loopback --addr; the bearer token would otherwise cross the network in plaintext")
			os.Exit(1)
		}
		httpSrv := server.NewStreamableHTTPServer(s)
		handler := requireBearerToken(token, httpSrv)
		if useTLS {
			fmt.Fprintf(os.Stderr, "jules-pp-mcp serving MCP over streamable HTTPS at %s (bearer token required)\n", *addr)
			if err := http.ListenAndServeTLS(*addr, *tlsCert, *tlsKey, handler); err != nil {
				fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
				os.Exit(1)
			}
		} else {
			fmt.Fprintf(os.Stderr, "jules-pp-mcp serving MCP over streamable HTTP at %s (bearer token required)\n", *addr)
			if err := http.ListenAndServe(*addr, handler); err != nil {
				fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
				os.Exit(1)
			}
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown --transport %q (supported: stdio, http)\n", *transport)
		os.Exit(2)
	}
}

// isLoopbackAddr reports whether addr (host:port, possibly with an empty
// host) binds only to the local machine. An empty host (e.g. ":7777") binds
// every interface, which is reachable from other hosts and is therefore not
// loopback.
func isLoopbackAddr(addr string) bool {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		host = addr
	}
	if host == "" {
		return false
	}
	if host == "localhost" {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// requireBearerToken rejects any request whose Authorization header does not
// present the configured token, using a constant-time comparison so response
// timing doesn't leak how much of the token matched.
func requireBearerToken(token string, next http.Handler) http.Handler {
	expected := "Bearer " + token
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		got := r.Header.Get("Authorization")
		if subtle.ConstantTimeCompare([]byte(got), []byte(expected)) != 1 {
			w.Header().Set("WWW-Authenticate", "Bearer")
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

// defaultTransport reads PP_MCP_TRANSPORT env when set, otherwise falls back
// to "stdio" so running the binary with no args keeps today's behavior.
// Container-hosted agents can pin the transport via env without a flag, which
// matches how hosted-agent process supervisors typically pass configuration.
func defaultTransport() string {
	if t := os.Getenv("PP_MCP_TRANSPORT"); t != "" {
		return t
	}
	return "stdio"
}
